import os
import cbmviz

# User Input
global_ops = cbmviz.cfg_default
cDir = os.path.dirname(os.path.abspath(os.sys.argv[0]))
sbml = os.path.join(cDir, "TestModels", "bigg2", "iIT341.xml") # H.pylori
file_name = "iIT341"
output_path = os.path.join(cDir, "{}_Output".format(file_name))


# test loading graph objects from other file formats
# --------------------------------------------------
# load graph object from JSON file (which was generated by cbmviz)
test_json_path = os.path.join(cDir, "OutputExamples", "pathwayLayout_FBAcolored", "iIT341_Output", "iIT341_output_whole.json")
test_json_graph = cbmviz.loadGraphObjFromFile(test_json_path)
cbmviz.saveGraphObjToTulipFile(test_json_graph, "test_json_graph.tlp")
# load graph object from GML file (which was generated by cbmviz)
test_gml_path = os.path.join(cDir, "OutputExamples", "pathwayLayout_FBAcolored", "iIT341_Output", "iIT341_output_whole.gml")
test_gml_graph = cbmviz.loadGraphObjFromFile(test_gml_path)
cbmviz.saveGraphObjToTulipFile(test_gml_graph, "test_gml_graph.tlp")
# store the graph object in a new graph_registry dict
# (same structure -> keys: graph names, values: [graph_obj, {graph_prop dict}])
test_graph_registry = cbmviz.createGraphDictFromGraphObj(test_json_graph)
#test_graph_registry = cbmviz.createGraphDictFromGraphObj(test_gml_graph)

# important note about GML files: they do not record a lot of info which means id, name and pathway graph property
# info (and also others) are lost! -> coloring fluxes requires ids, coloring pathways required ids and pathway data!

# use this new test graph_registry dict to do the coloring and export new results
fba_results = dict()
cbmviz.colorGraphs(global_ops, fba_results, test_graph_registry, output_path, file_name)
cbmviz.exportGraph(output_path, test_graph_registry, global_ops, cDir, file_name)

print(global_ops)
